using System.Diagnostics;
using System.Net;
using System.Text;
using System.Text.Json;
using FBS.Student.Native;
internal static class Program
{
 [STAThread]private static void Main(){int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
 using var listener=new HttpListener();listener.Prefixes.Add("http://127.0.0.1:4190/");listener.Start();string token=new('a',64),id=Guid.NewGuid().ToString(),jpeg="data:image/jpeg;base64,"+Convert.ToBase64String(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"fixture.jpg")));bool active=true,badToken=false;int requests=0;
 var server=Task.Run(async()=>{try{while(listener.IsListening){var c=await listener.GetContextAsync();if(c.Request.RawUrl!="/broadcast/local"||c.Request.Headers["X-FBS-Local-Token"]!=token){badToken=true;c.Response.StatusCode=403;}else{Interlocked.Increment(ref requests);var text=JsonSerializer.Serialize(new{broadcast=active?new{sessionId=id,sequence=1,jpeg}:null});var bytes=Encoding.UTF8.GetBytes(text);c.Response.ContentType="application/json";c.Response.ContentLength64=bytes.Length;await c.Response.OutputStream.WriteAsync(bytes);}c.Response.Close();}}catch(HttpListenerException){}catch(ObjectDisposedException){}});
 try{Application.EnableVisualStyles();using var form=new TeacherBroadcastForm(token);Check(form.FormBorderStyle==FormBorderStyle.None,"managed viewer has no student titlebar controls");Check(form.Bounds==Screen.PrimaryScreen!.Bounds,"viewer fills actual primary screen bounds");Check(form.TopMost,"viewer is above ordinary windows");Check(!form.Controls.OfType<Button>().Any(),"no per-session accept, reject or close button");using var timer=new System.Windows.Forms.Timer{Interval=100};var elapsed=Stopwatch.StartNew();bool imageSeen=false;
 timer.Tick+=(_,_)=>{try{if(elapsed.Elapsed.TotalSeconds>10)throw new TimeoutException("managed broadcast fixture timed out");if(!imageSeen&&form.Controls.OfType<PictureBox>().Single().Image is not null){imageSeen=true;Check(true,"teacher frame displayed without any student click");form.Close();Check(!form.IsDisposed,"student close request cannot dismiss a fresh managed broadcast");Check(form.Visible,"broadcast stays visible until teacher stops");active=false;}}catch(Exception ex){Console.Error.WriteLine(ex.Message);Environment.ExitCode=1;timer.Stop();form.Dispose();}};form.Shown+=(_,_)=>timer.Start();Application.Run(form);timer.Stop();Check(imageSeen&&form.IsDisposed,"teacher stop closes the full-screen viewer");Check(requests>0&&!badToken,"private native token used for every fixture request");
 active=true;using var stale=new TeacherBroadcastForm(token);var staleElapsed=Stopwatch.StartNew();Application.Run(stale);Check(stale.IsDisposed,"unchanged stale frame cannot keep student screen occupied");Check(staleElapsed.Elapsed.TotalSeconds>=3.5&&staleElapsed.Elapsed.TotalSeconds<9,"stale display exits on bounded local freshness timeout");Console.WriteLine($"Managed broadcast checks: {passed} passed. Owned loopback fixture only.");
 }catch(Exception ex){Console.Error.WriteLine("FAIL: "+ex.Message);Environment.ExitCode=1;}finally{listener.Stop();server.GetAwaiter().GetResult();}}
}
